from durationkit import parse_duration
from durationkit.parse import parse_duration as direct
valid = {'90': 90.0, '  42 ': 42.0, '0': 0.0, '0007': 7.0, '2d': 172800.0, '3h': 10800.0, '15m': 900.0, '45s': 45.0, '500ms': 0.5, '1h30m': 5400.0, '2d4h': 187200.0, '1m1s': 61.0, '1s500ms': 1.5, '1d1h1m1s1ms': 90061.001, '1d1s': 86401.0, '1h1ms': 3600.001, ' 1h 30m ': 5400.0, '\t1h\n30m\r': 5400.0, '01h030m': 5400.0, '0s': 0.0, '0d0h0m0s0ms': 0.0, '90m': 5400.0, '1500ms': 1.5}
for source, expected in valid.items():
    result = parse_duration(source)
    assert isinstance(result, float) and abs(result - expected) < 1e-9, (source, result)
invalid = ['', '   ', '\t\n', '-1', '-1h', '+1', '+1h', '1.5h', '.5s', '1e3s', '1_000s', '1,000s', '1x', '1H', '1MS', 'h', 'ms', 'abc', '1h1h', '1h 0h', '0s0s', '1ms1ms', '30m1h', '1ms1s', '1s1d', '0s0h', '1 h', '500 ms', '1\th', '1 0', '1h30', '1 30m', '1h!', '1h,30m', '1mss', 'Ⅰ', 'Ⅰh', '½', '½s', '①', '①m', '²s']
for source in invalid:
    try:
        parse_duration(source)
    except ValueError:
        pass
    else:
        raise AssertionError(source)
for source in [90, 0.5, None, True, b'90', []]:
    try:
        parse_duration(source)
    except TypeError:
        pass
    else:
        raise AssertionError(source)
assert direct is parse_duration
